import * as fs from 'fs';
import { Agent } from "@voltagent/core";
import { openai } from "@ai-sdk/openai";
import { registerOTEL } from '@vercel/otel';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-http';

// Configure telemetry to export traces to the local OTLP HTTP collector
registerOTEL({
  serviceName: 'voltagent-app',
  // @ts-ignore - Depending on the version, traceExporter might be accepted here
  traceExporter: new OTLPTraceExporter({
    url: 'http://localhost:4318/v1/traces',
  }),
});

const agent = new Agent({
  name: "Assistant",
  instructions: "You are a helpful assistant.",
  model: openai("gpt-4o-mini"),
  // Enable tracing functionality
  experimental_telemetry: {
    isEnabled: true,
    functionId: "assistant-agent",
  }
} as any);

async function main() {
  try {
    const result = await agent.run({ input: "Hello" });
    // result.text is usually where the response is in VoltAgent or AI SDK
    // But let's check what agent.run returns.
    const output = typeof result === 'string' ? result : (result as any).text || JSON.stringify(result);

    fs.writeFileSync('/home/user/app/output.log', output);
    console.log("Response logged to output.log");
  } catch (error) {
    console.error("Error during agent execution:", error);
  } finally {
    // Give some time for traces to be flushed before exiting
    setTimeout(() => {
      process.exit(0);
    }, 2000);
  }
}

main();

